<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { Coin, DocumentChecked, Files, Goods } from '@element-plus/icons-vue'
import { documentApi, financeApi, inventoryApi, reportApi } from '@/api/business'
import { useAuthStore } from '@/stores/auth'

const router=useRouter(),auth=useAuthStore(),loading=ref(false)
const financeSummary=reactive({receivable:0,paid:0,outstanding:0,outstandingOrders:0})
const inventorySummary=reactive({materialCount:0,stockValue:0,lowStockCount:0,expiryAlertCount:0})
const reportSummary=reactive({drafts:0,reviewing:0,archived:0})
const orders=ref<any[]>([]),purchases=ref<any[]>([]),issues=ref<any[]>([]),documents=ref<any[]>([]),reports=ref<any[]>([])

const documentSummary=computed(()=>({reviewing:documents.value.filter(x=>x.status==='REVIEWING').length,approved:documents.value.filter(x=>x.status==='APPROVED').length,published:documents.value.filter(x=>x.status==='PUBLISHED').length}))
const todos=computed(()=>({
  finance:[
    {label:'待确认收费单',count:orders.value.filter(x=>x.status==='DRAFT').length,to:{path:'/finance',query:{tab:'orders'}}},
    {label:'待登记收款',count:orders.value.filter(x=>['CONFIRMED','PART_PAID'].includes(x.status)).length,to:{path:'/finance',query:{tab:'orders'}}},
  ],
  inventory:[
    {label:'待审批采购申请',count:purchases.value.filter(x=>x.status==='SUBMITTED').length,to:{path:'/inventory',query:{tab:'purchase'}}},
    {label:'待审核验收入库',count:purchases.value.filter(x=>x.status==='RECEIPT_REVIEW').length,to:{path:'/inventory',query:{tab:'purchase'}}},
    {label:'待审核出库申请',count:issues.value.filter(x=>x.status==='SUBMITTED').length,to:{path:'/inventory',query:{tab:'issues'}}},
    {label:'库存预警处理',count:Number(inventorySummary.lowStockCount)+Number(inventorySummary.expiryAlertCount),to:{path:'/inventory',query:{tab:'stocks'}}},
  ],
  document:[
    {label:'待审核文件',count:documents.value.filter(x=>x.status==='REVIEWING').length,to:{path:'/documents'}},
    {label:'待发布文件',count:documents.value.filter(x=>x.status==='APPROVED').length,to:{path:'/documents'}},
  ],
  report:[
    {label:'待编制报告',count:reports.value.filter(x=>x.status==='DRAFT').length,to:{path:'/reports',query:{tab:'reports'}}},
    {label:'待审核报告',count:reports.value.filter(x=>x.status==='REVIEWING').length,to:{path:'/reports',query:{tab:'reports'}}},
  ],
}))
const money=(value:any)=>`¥ ${Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`
function go(to:any){router.push(to)}
async function load(){loading.value=true;try{
  const tasks:Promise<void>[]=[]
  if(auth.hasPermission('finance:charge:view'))tasks.push(Promise.all([financeApi.summary(),financeApi.orders()]).then(([summary,data])=>{Object.assign(financeSummary,summary);orders.value=data}))
  if(auth.hasPermission('inventory:stock:view'))tasks.push(Promise.all([inventoryApi.summary(),inventoryApi.purchases(),inventoryApi.issues()]).then(([summary,purchaseRows,issueRows])=>{Object.assign(inventorySummary,summary);purchases.value=purchaseRows;issues.value=issueRows}))
  if(auth.hasPermission('document:file:view'))tasks.push(documentApi.list().then(data=>{documents.value=data}))
  if(auth.hasPermission('report:report:view'))tasks.push(Promise.all([reportApi.summary(),reportApi.list()]).then(([summary,data])=>{Object.assign(reportSummary,summary);reports.value=data}))
  await Promise.all(tasks)
}finally{loading.value=false}}
onMounted(load)
</script>

<template>
  <section v-loading="loading" class="workbench-page">
    <div class="page-heading"><div><p>BUSINESS WORKBENCH</p><h1>工作台</h1></div><span>业务统计与待办事项</span></div>

    <section v-if="auth.hasPermission('finance:charge:view')" class="workbench-section finance-section">
      <header><div class="section-icon"><el-icon><Coin/></el-icon></div><div><h2>财务管理</h2><p>收费与收款业务概览</p></div></header>
      <div class="section-body"><div class="statistics-panel"><div class="statistics-grid"><article><span>累计应收</span><strong>{{money(financeSummary.receivable)}}</strong></article><article><span>累计实收</span><strong>{{money(financeSummary.paid)}}</strong></article><article><span>待收款</span><strong>{{money(financeSummary.outstanding)}}</strong><small>{{financeSummary.outstandingOrders}} 笔待跟进</small></article></div></div><div class="todo-panel"><h3>待办事项</h3><button v-for="item in todos.finance" :key="item.label" class="todo-item" @click="go(item.to)"><span>{{item.label}}</span><b>{{item.count}}</b></button></div></div>
    </section>

    <section v-if="auth.hasPermission('inventory:stock:view')" class="workbench-section inventory-section">
      <header><div class="section-icon"><el-icon><Goods/></el-icon></div><div><h2>物料管理</h2><p>库存、采购、入库与出库概览</p></div></header>
      <div class="section-body"><div class="statistics-panel"><div class="statistics-grid four"><article><span>库存品种</span><strong>{{inventorySummary.materialCount}}</strong></article><article><span>库存价值</span><strong>{{money(inventorySummary.stockValue)}}</strong></article><article><span>低库存</span><strong>{{inventorySummary.lowStockCount}}</strong></article><article><span>效期预警</span><strong>{{inventorySummary.expiryAlertCount}}</strong></article></div></div><div class="todo-panel"><h3>待办事项</h3><button v-for="item in todos.inventory" :key="item.label" class="todo-item" @click="go(item.to)"><span>{{item.label}}</span><b>{{item.count}}</b></button></div></div>
    </section>

    <section v-if="auth.hasPermission('document:file:view')" class="workbench-section document-section">
      <header><div class="section-icon"><el-icon><Files/></el-icon></div><div><h2>文件管理</h2><p>受控文件状态与审批概览</p></div></header>
      <div class="section-body"><div class="statistics-panel"><div class="statistics-flow"><article><strong>{{documentSummary.reviewing}}</strong><span>审核中</span></article><i>→</i><article><strong>{{documentSummary.approved}}</strong><span>待发布</span></article><i>→</i><article><strong>{{documentSummary.published}}</strong><span>已发布</span></article></div></div><div class="todo-panel"><h3>待办事项</h3><button v-for="item in todos.document" :key="item.label" class="todo-item" @click="go(item.to)"><span>{{item.label}}</span><b>{{item.count}}</b></button></div></div>
    </section>

    <section v-if="auth.hasPermission('report:report:view')" class="workbench-section report-section">
      <header><div class="section-icon"><el-icon><DocumentChecked/></el-icon></div><div><h2>报告管理</h2><p>报告编制、审核与归档概览</p></div></header>
      <div class="section-body"><div class="statistics-panel"><div class="statistics-flow"><article><strong>{{reportSummary.drafts}}</strong><span>编制中</span></article><i>→</i><article><strong>{{reportSummary.reviewing}}</strong><span>待审核</span></article><i>→</i><article><strong>{{reportSummary.archived}}</strong><span>已归档</span></article></div></div><div class="todo-panel"><h3>待办事项</h3><button v-for="item in todos.report" :key="item.label" class="todo-item" @click="go(item.to)"><span>{{item.label}}</span><b>{{item.count}}</b></button></div></div>
    </section>
  </section>
</template>

